<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
$rows=$conn->query("SELECT s.id,s.sale_date,s.buyer_name,s.buyer_phone,s.sale_price,s.payment_status,c.car_name,c.plate_number,IFNULL(p.paid,0) paid,(s.sale_price-IFNULL(p.paid,0)) balance FROM car_sales s JOIN cars c ON c.id=s.car_id LEFT JOIN(SELECT sale_id,SUM(amount) paid FROM sale_payments GROUP BY sale_id)p ON p.sale_id=s.id WHERE s.sale_price>IFNULL(p.paid,0) ORDER BY s.sale_date");
$total=0;$data=[];while($r=$rows->fetch_assoc()){$total+=(float)$r['balance'];$data[]=$r;}
$page_title='Outstanding Balances';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title"><div><h1 class="page-title">Outstanding Customer Balances</h1><p class="muted">Money still receivable from completed vehicle sales.</p></div><button class="btn" onclick="window.print()">Print</button></div><div class="card"><h2>Total Receivable: <?=money($total)?></h2><div class="table-responsive"><table class="table"><thead><tr><th>Sale Date</th><th>Car</th><th>Buyer</th><th>Phone</th><th>Sale</th><th>Paid</th><th>Balance</th><th class="no-print"></th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['sale_date'])?></td><td><?=e($r['car_name'].' / '.car_sales_plate_label($r['plate_number']))?></td><td><?=e($r['buyer_name'])?></td><td><?=e($r['buyer_phone']?:'—')?></td><td><?=money($r['sale_price'])?></td><td><?=money($r['paid'])?></td><td><?=money($r['balance'])?></td><td class="no-print"><a class="btn btn-green" href="../sales/payment.php?id=<?=$r['id']?>">Collect</a></td></tr><?php endforeach;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
